// The ⋯ menu (app.js) in jsdom against the rendered upstream list.
// Usage: node menu.js <upstreams.html> <path to app.js>
const {JSDOM}=require("jsdom");const fs=require("fs");
const html=fs.readFileSync(process.argv[2],"utf8").replace(/<script[^>]*src=[^>]*><\/script>/g,"");
const js=fs.readFileSync(process.argv[3],"utf8");
let fails=0; const ok=(c,m)=>{ if(!c){fails++;console.log("FAIL",m);} else console.log("ok  ",m); };
const dom=new JSDOM(html,{runScripts:"outside-only",pretendToBeVisual:true,url:"http://localhost/admin/upstreams"});
const w=dom.window,d=w.document; w.eval(js);
const menus=[...d.querySelectorAll("[data-menu]")];
const btn=m=>m.querySelector("[data-menu-button]"), list=m=>m.querySelector("[role=menu]"), items=m=>[...list(m).querySelectorAll("[role=menuitem]")];
const key=(el,k)=>el.dispatchEvent(new w.KeyboardEvent("keydown",{key:k,bubbles:true,cancelable:true}));
ok(menus.length>=2,"a menu on every row");
ok(menus.every(m=>list(m).hidden&&btn(m).getAttribute("aria-expanded")==="false"),"all closed at first");
ok(menus.every(m=>btn(m).getAttribute("aria-controls")===list(m).id&&btn(m).getAttribute("aria-haspopup")==="menu"&&list(m).getAttribute("role")==="menu"),"button and list are wired for screen readers");
const [a,b]=menus;
btn(a).click();
ok(!list(a).hidden&&btn(a).getAttribute("aria-expanded")==="true","the button opens the menu");
ok(d.activeElement===items(a)[0],"the first item takes the focus");
ok(items(a).map(i=>i.textContent.trim()).join()==="Details,Edit,Delete","items: "+items(a).map(i=>i.textContent.trim()));
key(d.activeElement,"ArrowDown"); ok(d.activeElement===items(a)[1],"ArrowDown moves on");
key(d.activeElement,"End"); ok(d.activeElement===items(a)[2],"End goes to the last item");
key(d.activeElement,"ArrowDown"); ok(d.activeElement===items(a)[0],"ArrowDown wraps");
key(d.activeElement,"ArrowUp"); ok(d.activeElement===items(a)[2],"ArrowUp wraps back");
key(d.activeElement,"Home"); ok(d.activeElement===items(a)[0],"Home goes to the first item");
key(d.activeElement,"Escape");
ok(list(a).hidden&&btn(a).getAttribute("aria-expanded")==="false"&&d.activeElement===btn(a),"Escape closes and returns to the button");
btn(a).click(); btn(b).click();
ok(list(a).hidden&&!list(b).hidden,"opening another menu closes the first");
d.body.click();
ok(list(b).hidden,"a click outside closes it");
btn(a).click(); btn(a).click();
ok(list(a).hidden,"the button toggles");
btn(a).focus(); key(btn(a),"ArrowDown");
ok(!list(a).hidden&&d.activeElement===items(a)[0],"ArrowDown on the button opens it");
key(d.activeElement,"Tab");
ok(list(a).hidden,"Tab leaves and closes it");
btn(a).focus(); key(btn(a),"ArrowUp");
ok(!list(a).hidden&&d.activeElement===items(a)[2],"ArrowUp on the button opens it on the last item");
items(a)[0].click();
ok(list(a).hidden,"choosing an item closes the menu");
ok(d.querySelector("[data-modal]").hasAttribute("open"),"Details opened its dialog");
console.log(fails?"FAILED "+fails:"ALL OK"); process.exit(fails?1:0);
